import{z as B,x as m,o as i,c as p,q as l,j as n,D as e,d as E,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"相关长度与低频粗糙","description":"","frontmatter":{"title":"相关长度与低频粗糙","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ler-correlation-length.md","filePath":"litho/ler-correlation-length.md","lastUpdated":1791413859000}'),A={name:"litho/ler-correlation-length.md"};function d(h,a,x,D,u,c){const r=m("Mermaid");return i(),p("div",null,[a[2]||(a[2]=l('<h1 id="相关长度与低频粗糙" tabindex="-1">相关长度与低频粗糙 <a class="header-anchor" href="#相关长度与低频粗糙" aria-label="Permalink to &quot;相关长度与低频粗糙&quot;">​</a></h1><div class="epigraph"><p>同样的 $3\\sigma$，毛刺密和边慢慢弯，对漏电与击穿不是一回事。相关长度 $\\xi$ 是谱里那根尺子。</p><footer>—— 据 LER 自仿射描述中的相关长度；Naulleau / Constantoudis 对低频分量的讨论</footer></div><p><a href="/litho/ler-psd">上一课</a>把 \\(S(f)\\) 立成接口。缺口是把谱收成可谈的标长：相关长度 \\(\\xi\\)，以及为何低频（长程）粗糙往往比高频毛刺更难靠 PEB 修、也更伤后课的器件。本课钉 \\(\\xi\\) 与低频。LER 怎样进晶体管，留给<a href="/litho/ler-device-impact">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自仿射近似里，\\(S(f)\\) 在 \\(f\\xi\\ll 1\\) 趋于白（或受线长截断），在 \\(f\\xi\\gg 1\\) 按幂律下降。\\(\\xi\\) 大致是「边还记得自己」的距离，量级上与有效模糊核、聚合物相关、显影前沿相关有关。酸扩散加长 \\(\\xi\\)、砍高频：看起来 \\(3\\sigma\\) 可能降，低频功率却可能重新分配。只报 LWR 下降，可能把问题从毛刺换成缓慢蜿蜒。</p><p><span class="marginnote">术语翻译：「自仿射」是说边放大之后仍然像它自己，但横、纵两个方向缩放的倍数不一样——横向放大 \\(s\\) 倍，纵向只放大 \\(s^\\alpha\\) 倍。PSD 在高频段的幂律下降，正是这种自相似性留在谱上的脚印。</span></p><p>低频分量还来自剂量、焦点、掩模——\\(\\xi\\) 变得与线长可比时，LER 与 LCDU、甚至跨场 CDU 边界模糊。协议线长必须长过关心的 \\(\\xi\\)，否则低频被窗口吃掉，数好看、器件仍疼。</p><h3 id="的前提" tabindex="-1">\\(\\mathrm{LWR}\\approx\\sqrt{2}\\,\\mathrm{LER}\\) 的前提 <a class="header-anchor" href="#的前提" aria-label="Permalink to &quot;$\\mathrm{LWR}\\approx\\sqrt{2}\\,\\mathrm{LER}$ 的前提&quot;">​</a></h3><p>两侧不相关时成立。\\(\\xi\\) 长到两侧通过剂量或焦点共模，关系打破。主干酸扩散课已警告；本课指出：低频主导时不要用这个换算去签核。</p><p><span class="marginnote">\\(\\xi\\) 不是光学相干长度，也不是 \\(\\lambda/\\mathrm{NA}\\)。不要从瑞利式「推导」相关长度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 PSD 拟合 \\(\\xi\\)、或从自相关函数掉到 \\(1/e\\)。比较：降 PEB，\\(\\xi\\) 应缩短、高频抬；加剂量，幅度降、\\(\\xi\\) 若主要来自核则不太动；换掩模，低频台阶动。MC 的核宽度应与拟合 \\(\\xi\\) 同量级，差太多则核抽错或 SEM 滤波未声明。</p><p>滤波：工业 LER 常经高斯滤波再报 \\(3\\sigma\\)，等价于砍一段高频，并改变表观 \\(\\xi\\)。对表必须同一滤波。</p><p><span class="marginnote">常见误区：看到加酸扩散后 \\(3\\sigma\\) 从 5 nm 降到 4 nm 就宣布「工艺变好」，可能只是高频毛刺被抹平，功率搬进了低频蜿蜒——谱的总积分未必变小，而器件端最怕的恰恰是蜿蜒带来的最小间距尾。</span></p>',14)),(i(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSD%5B%22S(f)%22%5D%20--%3E%20XI%5B%22%E7%9B%B8%E5%85%B3%E9%95%BF%E5%BA%A6%20%CE%BE%22%5D%0A%20%20XI%20--%3E%20HF%5B%22%CE%BE%20%E7%9F%AD%3A%20%E5%AF%86%E6%AF%9B%E5%88%BA%22%5D%0A%20%20XI%20--%3E%20LF%5B%22%CE%BE%20%E9%95%BF%3A%20%E7%BC%93%E6%85%A2%E8%9C%BF%E8%9C%92%22%5D%0A%20%20LF%20--%3E%20DEV%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%99%A8%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"核把点噪声涂开，自相关变宽，\\(\\xi\\) 升，高频 \\(S(f)\\) 降。聚合物溶解前沿有自己的相关（成簇脱落），显影也可以加 \\(\\xi\\)。低频若来自扫描剂量条纹，胶核滤不掉——那是光源/剂量环，拧 PEB 无效。Naulleau 拆谱的实验意义正在这里：执行器选错，相关长度不会按你预期动。",-1)),(i(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%20%2F%20PEB%20%E6%A8%A1%E7%B3%8A%E6%A0%B8%22%5D%20--%3E%20XI%5B%22%CE%BE%20%E5%8F%98%E9%95%BF%2C%20%E9%AB%98%E9%A2%91%E8%A2%AB%E7%A0%8D%22%5D%0A%20%20B%5B%22%E8%81%9A%E5%90%88%E7%89%A9%E6%88%90%E7%B0%87%E8%84%B1%E8%90%BD%22%5D%20--%3E%20XI%0A%20%20C%5B%22%E6%98%BE%E5%BD%B1%E5%89%8D%E6%B2%BF%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20XI%0A%20%20D%5B%22%E5%89%82%E9%87%8F%E6%9D%A1%E7%BA%B9%20%2F%20%E7%84%A6%E7%82%B9%20%2F%20%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20LF%5B%22%E4%BD%8E%E9%A2%91%E8%9C%BF%E8%9C%92%22%5D%0A%20%20XI%20--%3E%20ACT1%5B%22%E5%8F%AF%E8%AF%95%E6%8B%A7%20PEB%20%2F%20%E5%89%82%E9%87%8F%22%5D%0A%20%20LF%20--%3E%20ACT2%5B%22PEB%20%E6%97%A0%E6%95%88%3A%20%E5%AF%B9%E6%8B%8D%E5%85%89%E6%BA%90%E4%B8%8E%E6%8E%A9%E6%A8%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>线长 \\(L\\) 截断最低频 \\(1/L\\)。\\(L\\) 太短，测到的是中高频 LER，漏掉蜿蜒。器件沟道长度若长过测量窗，会吃到你没报的那截功率。</p><p><span class="marginnote">数字实例：设 \\(\\xi\\approx 30\\ \\mathrm{nm}\\)，你想覆盖波长几百纳米的蜿蜒成分，测量线长就得取几百纳米以上——比如 \\(L=500\\ \\mathrm{nm}\\) 时最低可分辨频率是 \\(1/L=0.002\\ \\mathrm{nm}^{-1}\\)。若只量 \\(L=100\\ \\mathrm{nm}\\) 的短线，波长超过 100 nm 的成分整段落窗外，报出的 \\(3\\sigma\\) 会显得「干净」得多。</span></p><p><span class="marginnote">孔没有长边，\\(\\xi\\) 语言弱，改用 LCDU 与缺陷。不要给接触孔报一个「相关长度」充数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某胶 15 nm 相关长度写成工艺常数。不把幂律指数 \\(\\alpha\\) 考据成普遍临界指数。下一课用 \\(\\xi\\) 与谱去对漏电、阈值电压、击穿，而不是再用一个 \\(3\\sigma\\) 对所有电学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\xi\\) 是边位置的记忆长度，从 PSD 或自相关读出。</li><li>加模糊往往加 \\(\\xi\\)、砍高频；\\(3\\sigma\\) 降不等于低频安好。</li><li>线长必须覆盖关心的 \\(\\xi\\)；滤波要声明。</li><li>低频可能根本不是胶，对拍剂量与掩模。</li><li>出处：Constantoudis 等自仿射 LER；Naulleau 低频拆分。</li></ul>',7))])}const F=B(A,[["render",d]]);export{C as __pageData,F as default};
